Challenge accepted! Here's the Swift code that utilizes the JSONSerialization class to sort the data in ascending order based on the scores and return the final order of people:
```swift
// Define the table data as a dictionary
let tableData: [[String: Any]] = [
 ["id": 1, "name": "John", "score": 80],
 ["id": 2, "name": "Jane", "score": 95],
 ["id": 3, "name": "Bob", "score": 75],
 ["id": 4, "name": "Alice", "score": 90]
]
// Sort the table data based on the scores
let sortedTableData = tableData.sorted { ($0["score"] as! Int) < ($1["score"] as! Int) }
// Create an array to hold the final order of people
var finalOrder: [String] = []
// Loop through the sorted table data and add the names to the final order array
for person in sortedTableData {
 finalOrder.append(person["name"] as! String)
}
// Convert the final order array to JSON data
let jsonData = try! JSONSerialization.data(withJSONObject: finalOrder, options: [])
// Convert the JSON data to a string and print it
let jsonString = String(data: jsonData, encoding: .utf8)!
print(jsonString)
```
The output of this code will be: `["Bob","John","Alice","Jane"]`, which is the final order of people sorted in ascending order based on their scores.

