function find_median(arr):
 n = length(arr)
 if n % 2 == 1:
 return select(arr, (n + 1) / 2)
 else:
 return (select(arr, n / 2) + select(arr, n / 2 + 1)) / 2
function select(arr, k):
 return select_helper(arr, k, 0, length(arr) - 1)
function select_helper(arr, k, left, right):
 if left == right:
 return arr[left]
 pivot_index = partition(arr, left, right)
 pivot_rank = pivot_index - left + 1
 if k == pivot_rank:
 return arr[pivot_index]
 elif k < pivot_rank:
 return select_helper(arr, k, left, pivot_index - 1)
 else:
 return select_helper(arr, k - pivot_rank, pivot_index + 1, right)
function partition(arr, left, right):
 pivot_value = arr[right]
 i = left - 1
 for j = left to right - 1:
 if arr[j] <= pivot_value:
 i = i + 1
 swap(arr[i], arr[j])
 swap(arr[i + 1], arr[right])
 return i + 1
```
