```
import java.util.*;
public class DijkstraAlgorithm {
 private final Map> graph;
 public DijkstraAlgorithm(Map> graph) {
 this.graph = graph;
 }
 public List shortestPath(String start, String end) {
 final Map distances = new HashMap<>();
 final Map previous = new HashMap<>();
 PriorityQueue nodes = new PriorityQueue<>();
 for (String vertex : graph.keySet()) {
 if (vertex.equals(start)) {
 distances.put(vertex, 0);
 nodes.add(vertex);
 } else {
 distances.put(vertex, Integer.MAX_VALUE);
 }
 previous.put(vertex, null);
 }
 while (!nodes.isEmpty()) {
 String smallest = nodes.poll();
 if (smallest.equals(end)) {
 final List path = new ArrayList<>();
 while (previous.get(smallest) != null) {
 path.add(smallest);
 smallest = previous.get(smallest);
 }
 Collections.reverse(path);
 return path;
 }
 if (distances.get(smallest) == Integer.MAX_VALUE) {
 break;
 }
 for (Map.Entry neighborEntry : graph.get(smallest).entrySet()) {
 String neighbor = neighborEntry.getKey();
 int distance = neighborEntry.getValue();
 int alt = distances.get(smallest) + distance;
 if (alt < distances.get(neighbor)) {
 distances.put(neighbor, alt);
 previous.put(neighbor, smallest);
 nodes.add(neighbor);
 }
 }
 }
 return new ArrayList<>(distances.keySet());
 }
 public static void main(String[] args) {
 Map> graph = new HashMap<>();
 graph.put("A", new HashMap<>() {{
 put("B", 5);
 put("C", 10);
 }});
