{
 // Absolute path example
 fs::path absolutePath = "/home/user/Documents/example.txt";
 std::cout << "Absolute path: " << absolutePath << std::endl;
 // Relative path example
 fs::path relativePath = "../Downloads/example.txt";
 std::cout << "Relative path: " << relativePath << std::endl;
 // Get absolute path from relative path
 fs::path absoluteFromRelative = fs::absolute(relativePath);
 std::cout << "Absolute path from relative: " << absoluteFromRelative << std::endl;
 return 0;
}
```
In this example, we use the `std::filesystem` library to work with file paths. We first define an absolute path and a relative path. We then use the `fs::absolute()` function to get the absolute path from the relative path. 
When we run this program, we get the following output:
```
Absolute path: "/home/user/Documents/example.txt"
Relative path: "../Downloads/example.txt"
Absolute path from relative: "/home/user/Downloads/example.txt"
```
This demonstrates the differences between absolute and relative paths and how to work with them in C++.

