```
using System;
using System.Collections.Generic;
class Program
{
 static void Main(string[] args)
 {
 List sequence = new List { 'C', 'E', 'E', 'E', 'T', 'U', 'U', 'P', 'S', 'S', 'S' };
 List> variations = GenerateVariations(sequence);
 Console.WriteLine("Total number of variations: " + variations.Count);
 foreach (List variation in variations)
 {
 Console.WriteLine(string.Join("", variation));
 }
 }
 static List> GenerateVariations(List sequence)
 {
 List> variations = new List>();
 if (sequence.Count == 0)
 {
 variations.Add(new List());
 return variations;
 }
 char first = sequence[0];
 List rest = sequence.GetRange(1, sequence.Count - 1);
 List> subVariations = GenerateVariations(rest);
 foreach (List subVariation in subVariations)
 {
 for (int i = 0; i <= subVariation.Count; i++)
 {
 List variation = new List(subVariation);
 variation.Insert(i, first);
 if (!variations.Contains(variation))
 {
 variations.Add(variation);
 }
 }
 }
 return variations;
 }
}
```
The `GenerateVariations` method recursively generates all possible variations of the given sequence by taking the first character, generating all possible variations of the rest of the sequence, and inserting the first character at every possible position in each variation of the rest of the sequence.
